	cancel()
	if err := <-done; !errors.Is(err, context.Canceled) {
		t.Fatalf("pipeline error = %v, want context.Canceled", err)
	}
	if got := active.Load(); got != 0 {
		t.Fatalf("pipeline returned with %d active workers", got)
	}
}

